<script setup lang="ts">
import{computed,onBeforeUnmount,reactive,shallowReactive,ref,watch}from'vue'
import{useSession}from'../../session'
import{captureRequestScope}from'../../request-scope'
import{InboundWork}from'./inbound-work'
import{stockTransport,ownerOf,canManageStock,warehousePath,type InboundReceipt}from'./stock-client'
import type{StockPart}from'./stock-catalog'
const props=defineProps<{warehouseId:string;parts:StockPart[];authorized:boolean}>(),auth=useSession(),partId=ref(''),quantity=ref(''),source=ref(''),note=ref(''),confirmed=ref(false),localError=ref(''),currentBalance=ref(''),downloadBusy=ref(false)
let alive=true,balanceSlot=0,downloadSlot=0
const identity=computed(()=>JSON.stringify(ownerOf(auth))),writeAllowed=()=>props.authorized&&canManageStock(auth.identity)&&auth.phase==='NORMAL'
const wire=stockTransport(auth,()=>alive),work=shallowReactive(new InboundWork(wire,()=>ownerOf(auth),writeAllowed,d=>reactive(d)))
watch(()=>[props.warehouseId,identity.value],()=>{work.bind(props.warehouseId);partId.value='';quantity.value='';source.value='';note.value='';confirmed.value=false;currentBalance.value='';downloadBusy.value=false;++balanceSlot;++downloadSlot},{immediate:true,flush:'sync'})
watch(()=>[partId.value,quantity.value,source.value,note.value,props.authorized],()=>{confirmed.value=false},{flush:'sync'})
const writer=computed(writeAllowed)
const upload=computed(()=>work.draft?.upload),operation=computed(()=>work.draft?.operation),frozen=computed(()=>!!operation.value||!!upload.value&&['UNKNOWN','NOT_OBSERVED'].includes(upload.value.state))
async function invoke(fn:()=>unknown){localError.value='';try{await fn()}catch(e){localError.value=e instanceof Error?e.message:'操作未确认'}}
async function fileChosen(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(file)await work.select(file);(event.target as HTMLInputElement).value=''}
async function submit(){if(!confirmed.value||!props.parts.some(p=>p.id===partId.value))return;await invoke(()=>work.submit({partId:partId.value,quantity:quantity.value,source:source.value,batchNote:note.value}))}
async function balance(){const part=operation.value?.body.partId||partId.value;if(!part)return;const slot=++balanceSlot,w=props.warehouseId,scope=captureRequestScope(auth,()=>alive&&slot===balanceSlot&&props.warehouseId===w);currentBalance.value='';try{const r=await wire.send<{items:{partId:string;onHand:string}[]}>('GET',warehousePath(w)+'/balances?'+new URLSearchParams({partId:part,page:'1',size:'20'}),undefined,scope.current);if(scope.current()){if(!Array.isArray(r.items)||r.items.some(x=>x.partId!==part||typeof x.onHand!=='string'))throw Error('当前余额投影不符');currentBalance.value=r.items[0]?.onHand??'当前无余额记录'}}catch(e){if(scope.current())localError.value=e instanceof Error?e.message:'余额未确认'}}
async function download(){const u=upload.value;if(!u?.result||downloadBusy.value)return;const slot=++downloadSlot,w=props.warehouseId,scope=captureRequestScope(auth,()=>alive&&slot===downloadSlot&&upload.value===u&&props.warehouseId===w);downloadBusy.value=true;try{const b=await wire.download(warehousePath(w)+'/inbound-files/'+u.id+'/content',scope.current);if(!scope.current())return;if(b.size!==u.file.size||b.type!==u.mime)throw Error('下载大小或类型与原凭证不符');const url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=u.file.name.replace(/[\\/]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}catch(e){if(scope.current())localError.value=e instanceof Error?e.message:'下载失败'}finally{if(scope.current())downloadBusy.value=false}}
onBeforeUnmount(()=>{alive=false;++balanceSlot;++downloadSlot;work.dispose()})
</script>
<template><section class="panel inbound-panel"><h2>入库凭证与提交</h2><p>入库只增加现存量；不表示审批、领料、消耗、费用或维修已完成。</p><p v-if="!authorized" role="status">当前仓库和目录未重新核验；只可按原UUID查询，禁止上传或重交。</p><p v-if="localError||work.message" role="status">{{localError||work.message}}</p><fieldset v-if="authorized" :disabled="!writer||work.busy||frozen"><label for="inbound-part">授权备件</label><select id="inbound-part" v-model="partId"><option value="">请选择当前备件</option><option v-for="p in parts" :key="p.id" :value="p.id">{{p.code}} · {{p.name}} {{p.model}}（{{p.unit}}）</option></select><label>入库数量<input v-model="quantity" inputmode="numeric" maxlength="19" placeholder="正整数，使用字符串提交"></label><label>入库来源<textarea v-model="source" maxlength="1000"/></label><label>批次说明<textarea v-model="note" maxlength="1000"/></label><label>选择入库凭证<input type="file" accept="image/png,image/jpeg,application/pdf" @change="fileChosen"></label></fieldset>
<section v-if="upload"><p v-if="authorized">{{upload.file.name}} · {{upload.file.size}}字节 · {{upload.state==='READY'?'凭证已就绪':upload.state==='LOCAL'?'尚未上传':'上传结果待核对'}} · 原上传UUID {{upload.id}}</p><p>凭证由库存服务私有保存，不是工单附件；没有删除接口，不声明已清理。</p><button v-if="upload.state==='LOCAL'" :disabled="work.busy||!writer" @click="invoke(()=>work.upload(false))">明确上传凭证</button><button :disabled="work.busy" @click="invoke(()=>work.upload(true))">查询原上传UUID</button><button v-if="upload.state==='NOT_OBSERVED'" :disabled="work.busy||!authorized" @click="invoke(()=>work.upload(false))">显式同UUID同File重传</button><button v-if="upload.result&&authorized" :disabled="downloadBusy" @click="download">当前鉴权下载凭证</button></section>
<label v-if="!operation&&authorized"><input v-model="confirmed" type="checkbox" :disabled="!writer||upload?.state!=='READY'">确认当前仓库、备件、数量、来源、批次说明与原凭证；不自动重发</label><button v-if="!operation" :disabled="!confirmed||!writer||work.busy||upload?.state!=='READY'" @click="submit">确认入库</button>
<section v-if="operation" aria-label="原入库操作"><p v-if="authorized">原入库UUID {{operation.key}} · 原数量 {{operation.body.quantity}} · 原来源 {{operation.body.source}} · 原批次 {{operation.body.batchNote}}</p><button :disabled="work.busy" @click="invoke(()=>work.recover(true))">查询原入库UUID</button><button v-if="operation.state==='NOT_OBSERVED'" :disabled="work.busy||!authorized" @click="invoke(()=>work.recover(false))">显式原UUID原参数重交</button><p v-if="operation.result&&authorized">入库结果已确认：当时现存量 {{operation.result.onHand}} · 记录时间 {{operation.result.recordedAt}}。这是历史回执，不代表当前余额。</p><button v-if="authorized" :disabled="work.busy" @click="balance">重新查询当前余额</button><p v-if="currentBalance&&authorized">当前查询余额：{{currentBalance}}</p><button v-if="operation.state==='SUCCEEDED'" :disabled="!writer||work.busy" @click="work.newDraft();confirmed=false;quantity='';source='';note=''">明确开始下一次入库</button></section></section></template>
<style scoped>label{display:block;margin:12px 0}input:not([type=checkbox]),select,textarea{display:block;width:min(100%,540px);box-sizing:border-box;padding:9px;margin-top:6px;border:1px solid #cbd5d2;border-radius:6px;font:inherit}textarea{min-height:70px}button{font:inherit;padding:8px 12px;margin:6px;border:1px solid #b9ccc7;border-radius:6px;background:#f6faf8}button:disabled{opacity:.5}fieldset{border:0;padding:0}p{overflow-wrap:anywhere}</style>
